import React, { useState, useEffect } from 'react';

export default function App() {
  // Estado para a lista de processos
  const [processos, setProcessos] = useState(() => {
    const salvo = localStorage.getItem('adv_processos');
    return salvo ? JSON.parse(salvo) : [];
  });

  // Estado para o formulário
  const [novoProcesso, setNovoProcesso] = useState({ cliente: '', numero: '', prazo: '', status: 'No Prazo' });

  // Salvar no navegador automaticamente
  useEffect(() => {
    localStorage.setItem('adv_processos', JSON.stringify(processos));
  }, [processos]);

  const adicionarProcesso = () => {
    if (!novoProcesso.cliente || !novoProcesso.prazo) return alert("Preencha Cliente e Prazo!");
    setProcessos([...processos, { ...novoProcesso, id: Date.now() }]);
    setNovoProcesso({ cliente: '', numero: '', prazo: '', status: 'No Prazo' });
  };

  const removerProcesso = (id) => {
    setProcessos(processos.filter(p => p.id !== id));
  };

  return (
    <div style={s.body}>
      {/* HEADER */}
      <header style={s.header}>
        <div style={s.container}>
          <h1 style={s.logo}>LEX<span>CONTROLE</span></h1>
          <p style={s.subLogo}>Painel de Gestão Jurídica</p>
        </div>
      </header>

      <div style={s.container}>
        {/* FORMULÁRIO DE CADASTRO */}
        <section style={s.card}>
          <h3 style={s.cardTitle}>🆕 Cadastrar Novo Caso</h3>
          <div style={s.gridForm}>
            <input style={s.input} placeholder="Nome do Cliente" value={novoProcesso.cliente} onChange={e => setNovoProcesso({...novoProcesso, cliente: e.target.value})} />
            <input style={s.input} placeholder="Nº do Processo" value={novoProcesso.numero} onChange={e => setNovoProcesso({...novoProcesso, numero: e.target.value})} />
            <input style={s.input} type="date" value={novoProcesso.prazo} onChange={e => setNovoProcesso({...novoProcesso, prazo: e.target.value})} />
            <select style={s.input} value={novoProcesso.status} onChange={e => setNovoProcesso({...novoProcesso, status: e.target.value})}>
              <option value="Urgente">🚨 Urgente</option>
              <option value="No Prazo">✅ No Prazo</option>
              <option value="Aguardando">⏳ Aguardando</option>
            </select>
          </div>
          <button style={s.btnAdd} onClick={adicionarProcesso}>+ SALVAR NO PAINEL</button>
        </section>

        {/* LISTA DE PROCESSOS ATIVOS */}
        <section style={{marginTop: '30px'}}>
          <h3 style={{color: '#1e293b', marginBottom: '15px'}}>📁 Processos Ativos ({processos.length})</h3>
          {processos.length === 0 && <p style={{textAlign: 'center', color: '#94a3b8'}}>Nenhum processo cadastrado.</p>}
          
          <div style={s.gridProcessos}>
            {processos.map(p => (
              <div key={p.id} style={s.processoCard}>
                <div style={s.statusBadge(p.status)}>{p.status}</div>
                <h4 style={{margin: '10px 0 5px'}}>{p.cliente}</h4>
                <p style={s.textP}>Proc: {p.numero || 'Não informado'}</p>
                <p style={s.textP}>📅 Vencimento: <strong>{new Date(p.prazo).toLocaleDateString('pt-BR')}</strong></p>
                <button style={s.btnDel} onClick={() => removerProcesso(p.id)}>Arquivar</button>
              </div>
            ))}
          </div>
        </section>
      </div>
    </div>
  );
}

// ESTILIZAÇÃO PROFISSIONAL (CSS-in-JS)
const s = {
  body: { backgroundColor: '#f1f5f9', minHeight: '100vh', fontFamily: '"Inter", sans-serif', color: '#334155' },
  header: { background: '#0f172a', color: 'white', padding: '40px 0', marginBottom: '30px', textAlign: 'center' },
  container: { maxWidth: '900px', margin: '0 auto', padding: '0 20px' },
  logo: { margin: 0, letterSpacing: '2px', fontWeight: '800' },
  subLogo: { margin: 0, opacity: 0.6, fontSize: '14px' },
  card: { background: 'white', padding: '25px', borderRadius: '12px', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' },
  cardTitle: { marginTop: 0, marginBottom: '20px', fontSize: '18px' },
  gridForm: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', marginBottom: '15px' },
  input: { padding: '12px', borderRadius: '8px', border: '1px solid #e2e8f0', fontSize: '15px' },
  btnAdd: { width: '100%', padding: '15px', background: '#2563eb', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' },
  gridProcessos: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))', gap: '20px' },
  processoCard: { background: 'white', padding: '20px', borderRadius: '12px', borderLeft: '5px solid #2563eb', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.1)' },
  statusBadge: (status) => ({
    display: 'inline-block',
    padding: '4px 10px',
    borderRadius: '20px',
    fontSize: '11px',
    fontWeight: 'bold',
    color: 'white',
    background: status === 'Urgente' ? '#ef4444' : status === 'Aguardando' ? '#f59e0b' : '#10b981'
  }),
  textP: { margin: '5px 0', fontSize: '14px', color: '#64748b' },
  btnDel: { marginTop: '15px', background: 'none', border: 'none', color: '#ef4444', cursor: 'pointer', fontSize: '13px', padding: 0 }
};
